contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 fundAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fundAmount)); require(fundAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= fundAmount);
        c.Command{value: fundAmount}(address(this), bytes("")); if (__ESBMC_reverted()) return;

        uint256 balanceBeforeWithdraw = address(c).balance;
        uint256 ownerBefore = address(this).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(
            !reverted
            && address(c).balance == 0
            && address(this).balance == ownerBefore + balanceBeforeWithdraw
        );
    }

    receive() external payable {}
}

